        Verse(book = "Jonas", chapter = 4, verseNumber = 6, text = "Lè sa a, Seyè a, Bondye a, fè yon ti pye masketi pouse. Li fè l' rive yon ti wotè pi wo pase Jonas pou mete yon ti lonbraj sou tèt li, pou li ka santi l' pi alèz. Jonas te kontan anpil lè li wè pye masketi a.", bookId = 32),
        Verse(book = "Jonas", chapter = 4, verseNumber = 7, text = "Men, nan denmen maten, anvan bajou kase, Bondye fè yon mawoka pike pye masketi a. Pye masketi a mouri.", bookId = 32),
